  "version": "2.0.8",
  "description": "OpenCode TUI plugin showing the current session tree (recent sessions or related child/spawned sessions) in the sidebar — one package for both OpenCode 1.x and 2.x",
  "type": "module",
  "types": "dist/index.d.ts",
