import { tui as tuiV1 } from "./v1";
const DEFAULT_MAX_SESSIONS = 10;
// storage 按插件分区，键名不需要再加前缀（命名空间随插件 id 变化：更名后旧状态重置，可接受）
const STORE_KEY = "panel";
const RECENT_LIMIT = 100;
const RELATED_LIMIT = 500;
/** Cap on per-session metadata backfill requests when the list omits metadata. */
const METADATA_GET_CAP = 60;
const INITIAL_VIEW = { open: true, maxSessions: DEFAULT_MAX_SESSIONS, mode: "recent" };
/** Metadata cache: full session + the time it was cached (TTL 5 min). Shared across panel instances on purpose. */
const META_TTL_MS = 5 * 60 * 1000;
const metaCache = new Map();
/** Placeholder used when the current session is not present in the fetched list. */
function stubSession(id) {
    return {
        id,
        projectID: "",
        cost: 0,
        tokens: { input: 0, output: 0, reasoning: 0, cache: { read: 0, write: 0 } },
        time: { created: 0, updated: 0 },
        title: id.slice(0, 8),
        location: { directory: "" },
    };
