function SessionsPanel(props) {
    const theme = props.context.theme;
    const data = props.context.data;
    const [view, updateView] = props.context.storage.store(STORE_KEY, { initial: INITIAL_VIEW });
    const [rows, setRows] = createSignal([]);
    const [loading, setLoading] = createSignal(true);
    const [spinner, setSpinner] = createSignal(0);
    // 每次挂载独立：宿主在 sessionID 变化时会重建本组件，模块级状态会把「旧实例的在途请求」
    // 与新实例的拉取串在一起，导致新实例一次都不发请求、列表恒空。
    let inFlight = false;
    let pending = false;
    let lastFingerprint = "";
    /** Backfill what the list omits (tree metadata and/or the title), bounded. Cache + bounded concurrency. */
    const backfillMetadata = async (list) => {
        const now = Date.now();
        const withMeta = [];
        const misses = [];
        let gets = 0;
        for (const s of list) {
            // 缓存只补 list 缺失的字段；list 是新鲜真值，标题/agent 等一律以 list 为准，
            // 否则「创建时无标题」的缓存条目会把列表里的新标题压回 id 前缀。
            const cached = metaCache.get(s.id);
            const merged = cached && now - cached.at < META_TTL_MS ? mergeCachedSession(cached.s, s) : s;
            if (!needsBackfill(merged)) {
                metaCache.set(merged.id, { s: merged, at: now });
                withMeta.push(merged);
                continue;
            }
            if (gets >= METADATA_GET_CAP) {
                withMeta.push(merged);
                continue;
            }
            misses.push(merged);
        }
        // 有界并发（6）补齐 miss；失败 push 原 s（容错同现状）。
        let idx = 0;
        const worker = async () => {
            while (idx < misses.length) {
                const s = misses[idx++];
                try {
                    const got = await props.context.client.session.get({ sessionID: s.id });
                    const full = got ? mergeCachedSession(s, got) : s;
                    gets++;
                    metaCache.set(full.id, { s: full, at: Date.now() });
                    withMeta.push(full);
                }
                catch {
                    withMeta.push(s);
                }
            }
        };
        await Promise.all(Array.from({ length: Math.min(6, misses.length) }, worker));
        return withMeta;
    };
    // 会话列表只有本地 store 里已加载的那些，所以按内置会话列表对话框的口径直接查服务端。
    // Related 需要全量（含子会话与 spawn 派生），Recent 只要根会话（服务端在 LIMIT 之前过滤）。
    const fetchRows = async () => {
        // 响应式依赖必须在这里**一次性全部读完**，早退分支也要读完之后才 return。
        // Solid 每次 effect 重跑都会重建依赖集：若某次重跑走了「在途合并 / 折叠」的早退
        // （过去这些判断写在读 mode 之前），这一轮就只订阅了 view.open，mode / maxSessions /
        // sessionID / refreshTick 的订阅被注销 → 之后切 Recent/Related 不再触发重取（表象：
        // 标签变了、列表不动，直到某次会话事件偶然补一次刷新）。
        const open = view.open;
        const mode = view.mode; // 同步段读取 → 被 createEffect 追踪（切换模式/改条数会自动重取）
        const max = view.maxSessions > 0 ? view.maxSessions : DEFAULT_MAX_SESSIONS;
        const sid = props.sessionID;
        const tick = props.refreshTick(); // 依赖：attach/detach 等命令主动触发时重取
        if (!open) {
            // 折叠：只记脏，零网络。展开时补拉。
            pending = true;
            return;
        }
        if (inFlight) {
            // 在途：合并到本轮结束后的下一次。
            pending = true;
            return;
        }
        if (!sid) {
            // 空 id（导航瞬态）：不发请求，避免 stubSession(undefined) 抛错导致列表空。
            setLoading(false);
            return;
        }
        inFlight = true;
        try {
            const directory = (data.session.get(sid)?.location ?? data.location.default()).directory;
            try {
                const response = mode === "related"
                    ? await props.context.client.session.list({ directory, limit: RELATED_LIMIT, order: "desc" })
                    : await props.context.client.session.list({ directory, parentID: null, limit: RECENT_LIMIT, order: "desc" });
                const items = response.data;
                if (!Array.isArray(items))
                    return;
                // 过期丢弃：等待期间又导航到别的会话 → 本次结果已无用，交给新实例/新请求。
                if (sid !== props.sessionID)
                    return;
                const normDir = normalizePath(directory);
                const inDir = normDir ? items.filter((session) => normalizePath(session.location?.directory) === normDir) : items;
                const withMeta = await backfillMetadata(inDir);
                if (sid !== props.sessionID)
                    return; // 回填期间又导航了
                const next = mode === "related"
                    ? buildRelatedRows(sid, withMeta, stubSession, max)
                    : buildRecentRows(withMeta, max);
                // 行指纹短路：结构或标题/备注变化才 setRows（保留旧引用，`<For>` 零 diff）。
                // 标题是创建后异步补的（session.renamed），必须计入指纹，否则行会一直停在 id 前缀。
                const fp = rowsFingerprint(mode, max, tick, sid, next);
                if (fp !== lastFingerprint) {
                    setRows(next);
                    lastFingerprint = fp;
                }
            }
            catch {
                // 网络或服务端错误：保留旧数据
            }
            finally {
                setLoading(false);
            }
        }
        finally {
            inFlight = false;
            if (pending) {
                pending = false;
                void fetchRows();
            }
        }
    };
    // 只在真的有会话在跑时才开定时器，避免空转
    createEffect(() => {
        if (!rows().some((row) => data.session.status(row.s.id) === "running"))
            return;
        const timer = setInterval(() => setSpinner((frame) => (frame + 1) % SPINNER_FRAMES.length), 80);
        onCleanup(() => clearInterval(timer));
    });
    let fetchTimer;
    const debouncedFetch = () => {
        clearTimeout(fetchTimer);
        fetchTimer = setTimeout(() => void fetchRows(), 200);
    };
    onMount(() => {
        // 2.x 事件把字段放在 `data` 上（`session.renamed` → `{ sessionID, title }`），
        // 不是 1.x 的 `properties.info`；旧写法永远取不到 info，标题变更进不了缓存。
        // 缓存里只存完整记录：只给已缓存条目打补丁，绝不用半截对象覆盖已有记录。
        const patchCache = (sessionID, patch) => {
            if (!sessionID)
                return;
            const hit = metaCache.get(sessionID);
            if (!hit)
                return;
            metaCache.set(sessionID, { s: { ...hit.s, ...patch }, at: Date.now() });
        };
        const unsubscribe = [
            data.on("session.created", (ev) => {
                // 新会话此刻通常还没有标题（稍后由 session.renamed 补上）→ 不写半截缓存。
                metaCache.delete(ev.data.sessionID);
                debouncedFetch();
            }),
            data.on("session.renamed", (ev) => {
                patchCache(ev.data.sessionID, { title: ev.data.title });
                debouncedFetch();
            }),
            data.on("session.deleted", (ev) => {
                metaCache.delete(ev.data.sessionID);
                debouncedFetch();
            }),
            data.on("session.metadata.updated", (ev) => {
                patchCache(ev.data.sessionID, { metadata: ev.data.metadata });
                debouncedFetch();
            }),
        ];
        onCleanup(() => {
            clearTimeout(fetchTimer);
            for (const off of unsubscribe)
                off();
        });
    });
    // 初次拉取 + 模式/条数变化/命令触发（refreshTick）时重取：
    // 读取 view.mode / view.maxSessions / refreshTick 建立依赖。
    let lastMode;
    createEffect(() => {
        const mode = view.mode;
        // 模式切换是「重取 + 回填」级别的操作（Related 最多 500 条 + 60 次 metadata 补拉），
        // 期间必须给个可见反馈，否则看起来像点了没反应。
        if (mode !== lastMode) {
            lastMode = mode;
            setLoading(true);
        }
        void fetchRows();
    });
    const switchTo = (sessionID) => {
        if (sessionID === props.sessionID)
            return;
        props.context.ui.router.navigate({ type: "session", sessionID });
    };
    const toggleOpen = () => {
        const next = !view.open;
        void updateView((draft) => {
            draft.open = next;
        }).catch(() => { });
        // 展开且此前折叠期间有脏 → 补拉一次。
        if (next && pending) {
            pending = false;
            void fetchRows();
        }
    };
    const toggleMode = async () => {
        // 翻转写进 mutation 内部：连点两次时都基于「最新已落盘值」计算，不会两次都算出
        // 同一个 next（过去 next 在 mutation 外按 view.mode 算，写盘是异步的，连点=只切一次）。
        let next;
        try {
            await updateView((draft) => {
                draft.mode = draft.mode === "related" ? "recent" : "related";
                next = draft.mode;
            });
        }
        catch {
            next = undefined;
        }
        props.context.ui.toast.show({ message: `Sessions mode: ${next ?? view.mode}` });
    };
    const isRunning = (session) => data.session.status(session.id) === "running";
    // 行首状态格：**必须是访问器**。`<For>` 的 mapFn 只在 item 身份变化时重跑，Solid 的
    // insert thunk 也只订阅它读过的信号——建行时求值一次存成常量，就等于把那一帧永久冻结
    // （2.0.5 spinner 不转的根因）。同理 status 也要在访问器里读，运行/结束才会实时换字。
    const bulletChar = (row) => isRunning(row.s) ? spinnerChar(spinner()) : staticBullet(row.collapsed === true, !!row.s.parentID && !!row.s.agent);
    const bulletFg = (row) => {
        if (isRunning(row.s))
            return theme.text.feedback.info.base;
        return row.s.id === props.sessionID ? theme.text.feedback.success.base : theme.text.muted;
    };
    return (_jsxs("box", { children: [_jsxs("box", { flexDirection: "row", gap: 1, children: [_jsxs("box", { flexDirection: "row", gap: 1, onMouseDown: toggleOpen, children: [_jsx("text", { fg: theme.text.base, children: view.open ? "\u25BC" : "\u25B6" }), _jsx("text", { fg: theme.text.base, children: _jsx("b", { children: "Sessions" }) })] }), _jsx("text", { fg: theme.text.muted, children: "\u00B7" }), _jsx("box", { flexDirection: "row", onMouseDown: toggleMode, children: _jsx("text", { fg: theme.text.feedback.info.base, children: view.mode === "related" ? "Related" : "Recent" }) }), _jsx(Show, { when: rows().length > 0, children: _jsxs("text", { fg: theme.text.muted, children: ["(", rows().length, ")"] }) })] }), _jsx(Show, { when: view.open, children: _jsx(Show, { when: !loading(), fallback: _jsx("text", { fg: theme.text.muted, children: "Loading..." }), children: _jsx(Show, { when: rows().length > 0, fallback: _jsx("text", { fg: theme.text.muted, children: "No sessions yet" }), children: _jsx(For, { each: rows(), children: (row) => {
                                return (_jsxs("box", { flexDirection: "row", gap: 1, minWidth: 0, onMouseUp: () => switchTo(row.s.id), children: [_jsxs("text", { flexShrink: 0, fg: bulletFg(row), children: [_jsx(Show, { when: row.depth > 0, children: _jsx("span", { style: { fg: theme.text.muted }, children: INDENT.repeat(row.depth - 1) + "\u21B3 " }) }), bulletChar(row)] }), _jsx("text", { fg: row.s.id === props.sessionID ? theme.text.base : theme.text.muted, wrapMode: "word", flexGrow: 1, flexShrink: 1, minWidth: 0, children: displayTitleOf(row.s) + subagentNoteOf(row.s) })] }));
                            } }) }) }) })] }));
}
const tui = {
    id: "opencode-session-tree",
    setup(context) {
        let activeSessionID;
        const [refreshTick, setRefreshTick] = createSignal(0);
        const refresh = () => setRefreshTick((tick) => tick + 1);
        context.ui.slot({
            append: "sidebar.content",
            render: (input) => {
                activeSessionID = input.sessionID;
                return _jsx(SessionsPanel, { context: context, sessionID: input.sessionID, refreshTick: refreshTick });
            },
        });
        // 当前会话 id：优先取路由，其次用侧栏 slot 渲染时传入的 sessionID（保证命令默认作用于当前会话）。
        const resolveCurrentSessionID = () => {
            const route = context.ui.router.current();
            if (route.type === "session")
                return route.sessionID;
            return activeSessionID;
        };
        // Attach：把当前会话挂到选定主会话下（写入 metadata.spawnParentID，与 Detach 互逆）。
        const applyAttach = async (all, cur, target) => {
            if (target.id === cur || chainContains(indexById(all), target.id, cur)) {
                context.ui.toast.show({ message: "不能挂靠到自己或自己的子孙会话", variant: "warning" });
                return;
            }
            try {
                const got = await context.client.session.get({ sessionID: cur });
                const md = got?.metadata ?? {};
                if (nonEmpty(md["spawnParentID"]) === target.id) {
                    context.ui.toast.show({ message: `已经挂靠在「${displayTitleOf(target)}」`, variant: "info" });
                    return;
                }
                // 步骤 0 实测（v2.0.30）：session.update 对 metadata 是整体替换（非合并），
                // 故先取现有 metadata，加 spawnParentID 后整体回写。
                const next = { ...md, spawnParentID: target.id };
                await context.client.session.update({ sessionID: cur, metadata: next });
                // 事件直写：attach 更新的 metadata 直接写缓存。
                if (got?.id)
                    metaCache.set(cur, { s: { ...got, metadata: next }, at: Date.now() });
                context.ui.toast.show({ message: `已挂靠到「${displayTitleOf(target)}」`, variant: "success" });
                refresh();
            }
            catch {
                context.ui.toast.show({ message: "挂靠失败：无法更新会话元数据", variant: "error" });
            }
        };
        const attach = async (cur) => {
            const value = await context.ui.dialog.prompt({
                title: "挂靠到主会话",
                description: "输入主会话名称（部分匹配，跨项目搜索）",
                placeholder: "主会话名称",
            });
            if (value === undefined)
                return;
            const query = value.trim();
            if (!query) {
                context.ui.toast.show({ message: "名称不能为空", variant: "warning" });
                return;
            }
            // 跨项目取全会话（主会话可能不在当前目录）。实测：不带 directory 的 search 覆盖全部 location。
            let all = [];
            try {
                const res = await context.client.session.list({ search: query, limit: 50, order: "desc" });
                all = res.data ?? [];
            }
            catch { }
            const q = query.toLowerCase();
            const matches = all.filter((session) => session.id !== cur && (session.title ?? "").toLowerCase().includes(q));
            if (matches.length === 0) {
                context.ui.toast.show({ message: `未找到匹配「${query}」的会话`, variant: "warning" });
                return;
            }
            if (matches.length === 1) {
                await applyAttach(all, cur, matches[0]);
                return;
            }
            const chosen = await context.ui.dialog.select({
                title: `选择主会话（${matches.length}）`,
                placeholder: "筛选",
                options: matches.map((session) => ({
                    title: displayTitleOf(session),
                    value: session.id,
                    description: session.location?.directory,
                })),
            });
            if (chosen === undefined)
                return;
            const target = matches.find((session) => session.id === chosen);
            if (target)
                await applyAttach(all, cur, target);
        };
        const detach = async (cur) => {
            try {
                const got = await context.client.session.get({ sessionID: cur });
                const md = got?.metadata ?? {};
                if (!nonEmpty(md["spawnParentID"])) {
                    context.ui.toast.show({ message: "当前会话未挂靠任何主会话", variant: "warning" });
                    return;
                }
                // 整体替换语义：取现有 metadata，删掉 spawnParentID 键后整体回写。
                const next = Object.fromEntries(Object.entries(md).filter(([key]) => key !== "spawnParentID"));
                await context.client.session.update({ sessionID: cur, metadata: next });
                // 事件直写：detach 更新后的 metadata 直接写缓存。
                if (got?.id)
                    metaCache.set(cur, { s: { ...got, metadata: next }, at: Date.now() });
                context.ui.toast.show({ message: "已升格：脱离主会话会话树", variant: "success" });
                refresh();
            }
            catch {
                context.ui.toast.show({ message: "升格失败：无法更新会话元数据", variant: "error" });
            }
        };
        context.keymap.layer(() => ({
            mode: "global",
            commands: [
                {
                    id: "sessions.count",
                    title: "Sessions: Set Max Count",
                    description: "Set the maximum number of top-level sessions shown in the sidebar (Recent & Related; in Related, child sessions never count)",
                    group: "Sessions",
                    slash: { name: "sessions-count" },
                    palette: true,
                    async run() {
                        const [view, updateView] = context.storage.store(STORE_KEY, { initial: INITIAL_VIEW });
                        const value = await context.ui.dialog.prompt({
                            title: "Max Sessions",
                            description: "Maximum number of top-level sessions shown in the sidebar (1-100). In Related mode, child sessions are not counted",
                            placeholder: String(DEFAULT_MAX_SESSIONS),
                            value: String(view.maxSessions),
                        });
                        if (value === undefined)
                            return;
                        const count = Number.parseInt(value, 10);
                        if (!(count >= 1 && count <= 100)) {
                            context.ui.toast.show({ message: "Enter a number between 1 and 100", variant: "warning" });
                            return;
                        }
                        await updateView((draft) => {
                            draft.maxSessions = count;
                        });
                        context.ui.toast.show({ message: `Max sessions set to ${count}` });
                    },
                },
                {
                    id: "sessions.mode",
                    title: "Sessions: Toggle Mode",
                    description: "Switch the sidebar between Recent and Related view",
                    group: "Sessions",
                    slash: { name: "sessions-mode" },
                    palette: true,
                    async run() {
                        const [view, updateView] = context.storage.store(STORE_KEY, { initial: INITIAL_VIEW });
                        // 翻转写进 mutation 内部（同面板的 toggleMode）：避免连点时两次都算出同一个 next。
                        let next;
                        try {
                            await updateView((draft) => {
                                draft.mode = draft.mode === "related" ? "recent" : "related";
                                next = draft.mode;
                            });
                        }
                        catch {
                            next = undefined;
                        }
